// TH18 v1.00a Extra stage07 / st07bs.ecl::BossCard8 (source lines 2232-2293).
// Dependencies inlined: BossCard8_at 2295-2311, BossCard8_et 2313-2355.
// Source spell id 94, declared length / interrupt timeout 5940 frames.
// Shell: validation.md control-only no-body wrapper; +120 opening buffer.

const TIME_LIMIT: int = 6120;
const OPENING_BUFFER: int = 120;
const ORIGINAL_TIME_LIMIT: int = 5940;
const SPELL_ID: int = 94;

// TH18 type 12 ARROWHEAD, base radius 2.4; source colors 2 and 4 are valid.
const TH18_ARROWHEAD: int = 544;

// BossCard8_et emitter bullet EX chain (source 2323-2325):
//   etEx(1,0,0x2,1,...)          ANIM; birth animation stage omitted, retreat 4*0 speed = 0
//   etEx(1,0,-2147483648,60,...) WAIT 60
//   etEx(1,0,0x200000,60,...,3.0f,...) VELTIME: a=60, target scalar speed 3,
//                                 s=-9999994 keeps the current angle -> scalar accel 0.05
xformdef DRAGON_BULLET {
    wait(60);
    @60 set_accel(0.05fx);   // 3.0 px/frame over 60 updates
    set_accel(0fx);
}

// BossCard8_et. Source flags 303 leave this emitter without body/hit collision and
// with both offscreen-cull bits set; per enemy-state.md that emitter is carried as a
// task holding its own world coordinates (approved by the task note).
// moveBezier(200, t0x,t0y, PLAYER_X2,PLAYER_Y2, 0,0) is Hermite mode 8:
// x/y components in hermite slots 0/1, tangents are normalized-time.
async sub dragon_head(color: int, sx: fx, sy: fx, tx: fx, ty: fx, dcount: int) {
    hermite_start(0, sx, $player_x, tx, 0fx, 200);
    hermite_start(1, sy, $player_y, ty, 0fx, 200);
    var px: fx = hermite_value(0);
    var py: fx = hermite_value(1);
    var nx: fx = px;
    var ny: fx = py;
    var ox: fx = 0fx;        // last etOffsetRad vector, kept for the BossCard8_et_1040 loop
    var oy: fx = 0fx;
    var spin: int = rand(65536) - 32768;          // %A = %RANDRAD
    accum_start(0, 0fx, 0.4fx, 80);               // floatTime(0,%B,80,0,0,32)

    // BossCard8_et_572: 200 shots, one per frame, while the path runs.
    // End with the card interrupt: the source's next card starts with enmKillAll.
    for i in 0..200 {
        wait(1);
        if self_int(2) >= 5940 { return; }
        nx = hermite_value(0);
        ny = hermite_value(1);
        var dir: angle = atan2(ny - py, nx - px); // %FINAL_ANGLE from the movement delta
        px = nx;
        py = ny;
        var ra: int = rand(65536) - 32768;        // %RANDF2 * 0.17453292rad (+-10deg)
        var ang: angle = dir + (((ra * 1820) / 32768) as angle);
        spin = spin + 40503;                      // %A += 3.883222rad = 40503 BAM
        if spin > 32768 { spin = spin - 65536; }  // validRad(%A)
        var rr: int = rand(65536) - 32768;        // %RANDF2 * %B
        var u: fx = ((rr as fx) / 1024fx) / 32fx; // signed [-1,1) radius factor
        var radius: fx = u * accum_value(0);
        ox = radius * cos(spin as angle);         // etOffsetRad(1, %A, RANDF2*%B)
        oy = radius * sin(spin as angle);
        _ = fire(TH18_ARROWHEAD, color, nx + ox, ny + oy, 0fx, ang,
                 DRAGON_BULLET, none);
    }

    // BossCard8_et_1040: etAngle(1,%A,0); A+=; validRad; etDist(RANDF2*32); etOn; wait(3)
    // etOffsetRad keeps the value configured by the last 572 shot; etDist is along the
    // bullet angle captured before the increment.
    for j in 0..dcount {
        if self_int(2) >= 5940 { return; }
        var a2: angle = spin as angle;
        spin = spin + 40503;
        if spin > 32768 { spin = spin - 65536; }
        var rd: int = rand(65536) - 32768;        // %RANDF2 * 32
        var dist: fx = (rd as fx) / 1024fx;
        _ = fire(TH18_ARROWHEAD, color,
                 nx + ox + dist * cos(a2), ny + oy + dist * sin(a2),
                 0fx, a2, DRAGON_BULLET, none);
        wait(3);
    }
}

// BossCard8_at: five emitters on a +-60deg fan of 1400px Hermite start tangents.
// %I0 color and %I1 count are passed by value at creation (source 2273-2280).
sub boss_at(color: int) {
    var base: angle = aim_player() - 180deg;      // %A = %ANGLE_PLAYER - pi
    var d: int = hermite_value(0) as int;         // $I1 = _S(%F1)
    var x: fx = $self_x;
    var y: fx = $self_y;
    var a: angle = base + 60deg;                  // circlePos +1.0471976
    spawn dragon_head(color, x, y, 1400fx * cos(a), 1400fx * sin(a), d);
    a = base + 30deg;                             // +0.5235988
    spawn dragon_head(color, x, y, 1400fx * cos(a), 1400fx * sin(a), d);
    a = base;                                     // +0
    spawn dragon_head(color, x, y, 1400fx * cos(a), 1400fx * sin(a), d);
    a = base - 30deg;                             // -0.5235988
    spawn dragon_head(color, x, y, 1400fx * cos(a), 1400fx * sin(a), d);
    a = base - 60deg;                             // -1.0471976
    spawn dragon_head(color, x, y, 1400fx * cos(a), 1400fx * sin(a), d);
}

// moveRand(60,4,1.0) sample from movement.md, limits retuned to this card:
// moveLimit(0,128,384,64) -> clamp x[-192,192] y[96,160], direction inner x+-96 y112..144.
// int slot0 = next source movement step, fx0/fx1 = logical unit direction.
sub boss_arm_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -192fx { nx = -192fx; }
    if nx > 192fx { nx = 192fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
// int slot2 = card frame counter, int slot3 = movement armed flag.
// Source timeout: setInterrupt(0,0,5940,"Boss9") fires at card frame 5940; the
// phase timer carries the extra shell buffer, the attack itself stops here.
sub boss_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        var t: int = self_int(2) + 1;
        set_self_int(2, t);
        if self_int(3) != 0 { boss_arm_step(); }
        if t >= 5940 { return; }
    }
}
sub boss_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    set_self_int(3, 1);
    boss_arm_step();
}
sub boss_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -96fx {
        a = r / 3;
    } else if $self_x > 96fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }           // source normalizes only this branch
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    boss_begin_angle(a as angle);
}

// BossCard8 body: opening move, floatTime(0,%F1,3600,0,3,30), 1020/1464 loop.
// Timer/interrupt spellEx(94,5940) becomes the phase timer in the shell.
async sub boss_card8() {
    set_invuln(65535);
    set_hitbox(24fx);                             // source setHitbox(48,48) -> r=24
    set_hurtbox(30fx);                            // source BossCard8 setHurtbox(60,60) -> r=30
    move_to(120, 0fx, 128fx, EASE_QUAD_OUT);      // movePosTime(120,4,0,128)
    boss_wait(120);                               // +120 label
    hermite_start(0, 3fx, 30fx, 27fx, 27fx, 3600); // floatTime slot0: 3 -> 30 linear
    var c: int = 10000;                           // $C
    while c > 0 {
        c = c - 1;                                // BossCard8_1464 if ($C--)
        boss_at(2);                               // $I0 = 2
        boss_wait(130);
        if self_int(2) >= 5940 { break; }
        boss_move_rand();                         // moveRand(60,4,1.0)
        boss_wait(80);
        if self_int(2) >= 5940 { break; }
        boss_at(4);                               // $I0 = 4
        boss_wait(130);
        if self_int(2) >= 5940 { break; }
        boss_move_rand();
        boss_wait(80);
        if self_int(2) >= 5940 { break; }
    }
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);        // stop at the source interrupt
    loop { wait(1000); }                          // BossCard8_1552/1532
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 18000, 0, 0, 0, boss_card8);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
